#!/usr/bin/env python3
"""Generate the supported, deliberately small JSON Schema subset. No third-party tools."""
import argparse
import hashlib
import json
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / 'protocols/yingxue/schema.json'
SCHEMA = json.loads(SOURCE.read_text(encoding='utf-8'))
DEFS = SCHEMA['$defs']
def source_hash(path):
    # Git stores these text files with LF. A Windows editor may temporarily write
    # CRLF; generated files must remain identical before and after Git normalization.
    return hashlib.sha256(path.read_text(encoding='utf-8').encode('utf-8')).hexdigest()


HASH = source_hash(SOURCE)
HEADER = f'// Generated by scripts/generate_yingxue.py; do not edit.\n// Schema SHA-256 (LF): {HASH}\n'


def reference(schema):
    assert set(schema) == {'$ref'}, schema
    name = schema['$ref'].removeprefix('#/$defs/')
    assert name in DEFS and schema['$ref'] == '#/$defs/' + name
    return name


def kind(schema):
    if 'oneOf' in schema:
        assert set(schema) == {'oneOf'}
        return 'union'
    value = schema['type']
    if isinstance(value, list):
        assert value == ['string', 'null']
        return 'nullableString'
    return value


def quote(value):
    # Swift understands Unicode characters, but uses \u{...}, not JSON's \uXXXX.
    return json.dumps(value, ensure_ascii=False)


def case_name(value):
    assert re.fullmatch(r'[A-Za-z][A-Za-z0-9]*(?:\.[A-Za-z][A-Za-z0-9]*)*', value)
    first, *rest = value.split('.')
    return '`' + first[0].lower() + first[1:] + ''.join(part[0].upper() + part[1:] for part in rest) + '`'


def alternatives(schema):
    result = []
    for entry in schema['oneOf']:
        name = reference(entry)
        value = DEFS[reference(DEFS[name]['properties']['kind'])]['const']
        result.append((name, value))
    assert len({value for _, value in result}) == len(result)
    return result


def swift():
    output = [HEADER, 'import Foundation\n', 'public enum YingxueWire {', f'    public static let schemaSHA256 = "{HASH}"']
    rules = []
    for name, schema in DEFS.items():
        t = kind(schema)
        if t in ('string', 'nullableString'):
            assert set(schema) <= {'type','minLength','pattern','enum','const'}
            values = schema.get('enum', [schema['const']] if 'const' in schema else [])
            if values:
                assert t == 'string'
                assert len({case_name(v) for v in values}) == len(values), values
                output += [f'    public enum {name}: String, Codable, Hashable, Sendable {{']
                output += [f'        case {case_name(v)} = {quote(v)}' for v in values]
                output += ['    }']
            else:
                output += [f'    public typealias {name} = String' + ('?' if t == 'nullableString' else '')]
            pattern = quote(schema['pattern']) if 'pattern' in schema else 'nil'
            choices = '[' + ', '.join(map(quote, values)) + ']'
            rule = f'.string(nullable: {str(t == "nullableString").lower()}, minimum: {schema.get("minLength",0)}, pattern: {pattern}, choices: {choices})'
        elif t == 'integer':
            assert set(schema) <= {'type','minimum','maximum','const'}
            output += [f'    public typealias {name} = Int']
            minimum = schema.get('const', schema.get('minimum', -9007199254740991))
            maximum = schema.get('const', schema.get('maximum', 9007199254740991))
            rule = f'.integer(minimum: {minimum}, maximum: {maximum})'
        elif t == 'boolean':
            assert set(schema) == {'type'}
            output += [f'    public typealias {name} = Bool']
            rule = '.boolean'
        elif t == 'array':
            assert set(schema) <= {'type','items','uniqueItems'}
            item = reference(schema['items'])
            output += [f'    public typealias {name} = [{item}]']
            rule = f'.array(item: "{item}", unique: {str(schema.get("uniqueItems",False)).lower()})'
        elif t == 'object':
            assert set(schema) - {'x-sensitive'} == {'type','properties','required','additionalProperties'}
            assert schema['additionalProperties'] is False
            assert schema.get('x-sensitive', True) is True
            props, required = schema['properties'], set(schema['required'])
            assert required <= props.keys()
            output += [f'    public struct {name}: YingxueWireModel, Equatable {{', f'        public static let wireType = "{name}"']
            fields, assignments = [], []
            for key, prop in props.items():
                ptype = reference(prop)
                optional = key not in required
                output += [f'        public let {key}: {ptype}' + ('?' if optional else '')]
                fields += [f'{key}: {ptype}' + ('? = nil' if optional else '')]
                assignments += [f'            self.{key} = {key}']
            output += ['        public init(' + ', '.join(fields) + ') {', *assignments, '        }']
            if schema.get('x-sensitive'):
                output += ['        public var description: String { "[redacted]" }',
                           '        public var debugDescription: String { description }',
                           '        public var customMirror: Mirror { Mirror(self, children: [:]) }']
            output += ['        private enum CodingKeys: String, CodingKey { case ' + ', '.join(props) + ' }', '        public func encode(to encoder: any Encoder) throws {', '            var container = encoder.container(keyedBy: CodingKeys.self)']
            output += [f'            try container.' + ('encode' if key in required else 'encodeIfPresent') + f'({key}, forKey: .{key})' for key in props]
            output += ['        }', '    }']
            field_rules = ', '.join(f'{quote(key)}: .init(type: {quote(reference(prop))}, required: {str(key in required).lower()})' for key, prop in props.items())
            rule = f'.object([{field_rules}])'
        elif t == 'union':
            choices = alternatives(schema)
            output += [f'    public enum {name}: YingxueWireModel, Equatable {{', f'        public static let wireType = "{name}"']
            output += [f'        case {case_name(value)}({subtype})' for subtype,value in choices]
            output += ['        public init(from decoder: any Decoder) throws {', '            let container = try decoder.container(keyedBy: WireDiscriminator.self)', '            switch try container.decode(String.self, forKey: .kind) {']
            output += [f'            case {quote(value)}: self = .{case_name(value)}(try {subtype}(from: decoder))' for subtype,value in choices]
            output += ['            default: throw WireViolation(path: "$.kind", reason: .unknownVariant)', '            }', '        }', '        public func encode(to encoder: any Encoder) throws {', '            switch self {']
            output += [f'            case .{case_name(value)}(let value): try value.encode(to: encoder)' for _,value in choices]
            output += ['            }', '        }', '    }']
            rule = '.tagged([' + ', '.join(f'{quote(value)}: {quote(subtype)}' for subtype,value in choices) + '])'
        else:
            raise ValueError(t)
        rules += [f'        "{name}": {rule},']
    output += ['}', '']
    for name, schema in DEFS.items():
        if schema.get('x-sensitive'):
            output += [f'extension YingxueWire.{name}: CustomStringConvertible, CustomDebugStringConvertible, CustomReflectable {{}}']
    output += ['', 'enum GeneratedWireSchema {', '    static let rules: [String: WireRule] = [', *rules, '    ]', '}',
               'enum GeneratedModulePolicy {', '    static let requiredExports = [' + ', '.join(map(quote,SCHEMA['x-module']['requiredExports'])) + ']', '}', '']
    return '\n'.join(output)


def typescript():
    output = [HEADER]
    for name, schema in DEFS.items():
        t = kind(schema)
        if t in ('string','nullableString'):
            values = schema.get('enum', [schema['const']] if 'const' in schema else [])
            result = ' | '.join(map(quote,values)) if values else 'string'
            if t == 'nullableString': result += ' | null'
        elif t == 'integer': result = str(schema['const']) if 'const' in schema else 'number'
        elif t == 'boolean': result = 'boolean'
        elif t == 'array': result = 'ReadonlyArray<' + reference(schema['items']) + '>'
        elif t == 'union': result = ' | '.join(reference(value) for value in schema['oneOf'])
        elif t == 'object':
            fields = [f'  readonly {key}' + ('' if key in schema['required'] else '?') + ': ' + reference(prop) + ';' for key,prop in schema['properties'].items()]
            output += [f'export interface {name} {{', *fields, '}', '']
            continue
        output += [f'export type {name} = {result};', '']
    return '\n'.join(output)


def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true')
    args=parser.parse_args()
    outputs = {
        ROOT/'Packages/SnowlitKit/Sources/YingxueKit/Contract/GeneratedWire.swift': swift(),
        ROOT/'protocols/yingxue/yingxue.d.ts': typescript(),
        ROOT/'Packages/SnowlitKit/Sources/YingxueKit/Resources/SourceInspection/module-policy.js': HEADER + 'globalThis.SnowlitModulePolicy = Object.freeze(' + json.dumps(SCHEMA['x-module'],ensure_ascii=False,sort_keys=True) + ');\n',
    }
    assert set(SCHEMA['x-module']) == {'ecmaVersion','requiredExports','optionalExports','parameterCount'}
    assert set(SCHEMA['x-module']['requiredExports'] + SCHEMA['x-module']['optionalExports']) == set(DEFS['ExportName']['enum'])
    corpus_path = ROOT/'protocols/yingxue/fixtures/wire.json'
    corpus = json.loads(corpus_path.read_text(encoding='utf-8'))
    corpus_swift = [HEADER, '// Corpus SHA-256 (LF): ' + source_hash(corpus_path),
        'struct WireCorpusCase: Sendable {',
        '    let name: String; let type: String; let json: String; let valid: Bool',
        '    static let all: [WireCorpusCase] = [']
    for case in corpus:
        assert set(case) == {'name','type','json','valid'} and case['type'] in DEFS
        corpus_swift += ['        .init(name: ' + quote(case['name']) + ', type: ' + quote(case['type']) + ', json: ' + quote(case['json']) + ', valid: ' + str(case['valid']).lower() + '),']
    corpus_swift += ['    ]', '}', '']
    outputs[ROOT/'Packages/SnowlitKit/Tests/YingxueKitTests/GeneratedWireCorpus.swift'] = '\n'.join(corpus_swift)
    module_corpus_path = ROOT/'protocols/yingxue/fixtures/modules.json'
    module_corpus = json.loads(module_corpus_path.read_text(encoding='utf-8'))
    module_swift = [HEADER, '// Corpus SHA-256 (LF): ' + source_hash(module_corpus_path),
        'struct ModuleCorpusCase: Sendable {',
        '    let name: String; let source: String; let requirements: [String]; let reason: String?',
        '    static let all: [ModuleCorpusCase] = [']
    for case in module_corpus:
        assert set(case) == {'name','source','requirements','reason'}
        requirements='['+', '.join(map(quote,case['requirements']))+']'
        module_swift += ['        .init(name: ' + quote(case['name']) + ', source: ' + quote(case['source']) + ', requirements: ' + requirements + ', reason: ' + ('nil' if case['reason'] is None else quote(case['reason'])) + '),']
    module_swift += ['    ]', '}', '']
    outputs[ROOT/'Tests/SnowlitAppTests/Probes/GeneratedModuleCorpus.swift'] = '\n'.join(module_swift)
    for path, body in outputs.items():
        if args.check:
            if not path.exists() or path.read_text(encoding='utf-8') != body:
                raise SystemExit(f'Generated contract differs: {path.relative_to(ROOT)}')
        else:
            path.parent.mkdir(parents=True,exist_ok=True)
            path.write_text(body,encoding='utf-8',newline='\n')
    print(f'Yingxue schema {HASH}: ' + ('checked' if args.check else 'generated'))


if __name__ == '__main__': main()
